(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.03-t*0.5)*8+Math.cos((y+wy1)*0.025+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.028+t*0.45)*8+Math.sin((x+wx1)*0.022-t*0.55)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3)*40,0.11,2.1],
    [400+Math.cos(t*0.6+2)*70,200+Math.sin(t*0.4+1)*50,0.05,2.8],
    [200+Math.sin(t*0.45)*110,30+Math.cos(t*0.65+4)*60,0.09,1.8]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);}
  const act=aS/9,inh=iS/9;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+Math.cos(sy*0.06+t)*3+t*1.5)*0.15;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2+t*1.8)*0.5)*0.3;
  const radial=Math.sin(dist*0.08-t*2)*0.15;
  const raw=act-inh*0.7+bg*0.3+spiral+radial;
  const rd1=Math.tanh(raw*2.2),rd2=Math.tanh(raw*1.5+Math.sin(rd1*3)*0.3);
  const reaction=Math.tanh((rd1+rd2)*0.6);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-sy*0.18+t*0.7)*0.3)*1.5)*0.3;
  const dx=reaction-Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.0);
  const edge=Math.min(1,Math.abs(dx)*5);
  const blend=reaction*0.7+cell*0.2+edge*0.1,v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[18,85,115],[25,135,135],[80,170,120],[180,190,80],[220,170,60],[215,110,65],[185,65,70],[140,40,75],[85,25,65],[35,15,55],[5,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2+edge*0.15;
  const glow=Math.max(0,1-dist/200)*0.1;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(lum+glow))|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*(lum+glow))|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(lum+glow))|0
  ];
}
